from lib import *
S = SS('l31')
steps = [
    step("用 Python 解析 .git/index:版本 2,3 个条目,扩展块 TREE(82 字节,缓存的目录树)。每个条目除了路径和 blob hash,还有一份文件的 stat 信息:ctime、mtime(秒加纳秒)、dev、ino、权限模式、uid、gid、文件大小。逐字段与 os.stat 对比,三个文件全部一致(True)。git 创建这条记录时,把当时磁盘上文件的 stat 抄了一份存进去。", t=tl(S(1)), mark=lidx(S(1), 'a.txt', 'src/b.txt', 'src/deep/c.txt'), done=lidx(S(1), 'index 版本 2'), kv=KV([['条目里有', 'ctime、mtime、dev、ino、mode、uid、gid、size'], ['再加', 'blob hash、flags、路径'], ['来源', '创建条目时从磁盘 stat 抄来']], ['条目里有'])),
    step("git status 判断“没改”的方式:把磁盘上现在的 stat 和 index 里存的比较,全部一致就认为没改,不读文件内容。如果只是 touch(内容没变、mtime 变了),git 发现 stat 不同,就得读文件算 hash 确认内容没变;结果无输出,并且顺手把新的 stat 写回 index——a.txt 在 index 里的 mtime 从上一个值更新成了新的(秒数增加)。下一次 status 就又只比 stat 了。", t=tl(S(2)), mark=lidx(S(2), 'a.txt 在 index 里的 mtime', 'status 为空'), done=lidx(S(2), '只 touch'), kv=KV([['stat 一致', '认为没改,不读内容'], ['stat 不同', '读内容算 hash 再确认'], ['确认没改', '把新的 stat 写回 index']], ['stat 不同'])),
    step("stat 缓存的盲点:把 a.txt 原地改成同样 6 个字节的 HELLO,再把 mtime 恢复成原值。默认配置下 ctime 暴露了改动(原地写入会更新 ctime),git status 报告 M a.txt。把 core.trustctime=false 和 core.checkStat=minimal(只比较 mtime 和 size)打开,同样的改动再来一次,git status 和 git diff --stat 都没有任何输出;但 git hash-object a.txt(e427984d…)与 index 里的 hash(ce013625…)不同——内容确实变了。恢复默认配置后,git status 又报告 M a.txt。", t=tl(S(3)), mark=lidx(S(3), 'trustctime=false + checkStat=minimal', '两者不同', 'e427984d4a2c'), done=lidx(S(3), '默认配置', '恢复默认比较后', ' M a.txt'), kv=KV([['默认', 'ctime 也比较,原地改写会暴露'], ['trustctime=false + checkStat=minimal', '只比 mtime 和 size,可被伪造'], ['代价', '换来更少的重新哈希']], ['trustctime=false + checkStat=minimal'])),
    step("stat 缓存有多重要:10,000 个小文件的仓库,stat 缓存有效时 git status 29 ms;把 10,000 个文件的 mtime 全部改掉(内容不变)后第一次 git status 要重读所有文件算 hash,204 ms;等过 1 秒、再跑一次让 index 刷新之后,git status 又回到 29 ms。省的就是读 10,000 个文件的时间(差约 7 倍)。刚被改过的文件需要等一会儿才能恢复快速状态,原因在下一篇 racy git。", t=tl(S(4)), mark=lidx(S(4), '204 ms'), done=lidx(S(4), 'stat 缓存有效', '29 ms'), b=bars([['stat 缓存有效', 29, '29 ms'], ['mtime 全被改后的第一次', 204, '204 ms'], ['index 刷新之后', 29, '29 ms']], 204, mark=[1], done=[0, 2]), kv=KV([['10,000 个文件', 'stat 对 vs 重新哈希'], ['缓存有效', '29 ms'], ['缓存失效', '204 ms(约 7 倍)']], ['缓存失效'])),
    step("cp -a 把整个仓库复制到别处:文件内容和 mtime 保留,但 inode 和 ctime 变了,index 里的 ino、ctime 全部失效,第一次 git status 要重新哈希全部文件,734 ms,第二次又回到 28 ms。如果设置 core.checkStat=minimal 和 core.trustctime=false(只比 mtime 和 size),同样的 cp -a 之后第一次 git status 就只要 29 ms。这是搬仓库后第一次 status 特别慢的原因。", t=tl(S(5)), mark=lidx(S(5), '734 ms', '29 ms'), done=lidx(S(5), 'cp -a 之后第一次', '28 ms'), b=bars([['cp -a 后第一次', 734, '734 ms'], ['cp -a 后第二次', 28, '28 ms'], ['minimal + 无 ctime', 29, '29 ms']], 734, mark=[0], done=[1, 2]), kv=KV([['cp -a', 'inode、ctime 变了,stat 缓存全部失效'], ['第二次', '回到快速状态'], ['minimal', '只比较 mtime 和 size,不受影响']], ['cp -a'])),
]
A = mkarti('l31', 31, 'Git,index,stat,git status,性能,真实验证,动画演示',
    '解析 .git/index 里每个条目的 stat 缓存(ctime、mtime、dev、ino、mode、uid、gid、size)并与 os.stat 对账;git status 只在 stat 不同时才读文件;core.trustctime=false 加 core.checkStat=minimal 会让原地改写且恢复 mtime 的改动不可见;10,000 个文件时 stat 缓存失效使 git status 从 29 ms 变成 204 ms,cp -a 搬仓库后首次 status 734 ms。',
    'git status 在大仓库里为什么能这么快?答案是 index 里的 stat 缓存:只在文件的 stat 变了的时候才去读内容。这篇解析 index 条目、验证 touch 与原地改写时 status 的判断,再测 10,000 个文件时缓存有效与失效的差别,以及 cp -a 之后为什么第一次 status 特别慢。',
    [('29 vs 204 ms', '10,000 个文件的仓库,stat 缓存有效与全部失效时 git status 的耗时'), ('8 个字段', 'index 条目里缓存的 stat 信息:ctime、mtime、dev、ino、mode、uid、gid、size'), ('734 ms', 'cp -a 把仓库搬走后第一次 git status 的耗时(inode 与 ctime 全变),第二次只要 28 ms')],
    [('index 里的 stat', '<p>每个 index 条目除了路径、blob hash、flags,还存着该文件当时的 stat:ctime、mtime(秒与纳秒)、dev、ino、权限、uid、gid、大小。解析 .git/index 后逐字段与 <code>os.stat</code> 对比完全一致。</p>'),
     ('怎么判断没改', '<p><code>git status</code> 对每个文件先比较 stat:全部一致就认定没改,不读内容;只要有字段不同,才去读内容算 hash。如果内容其实没变(比如只是 touch),git 会把新的 stat 写回 index,下次又能走快速路径。</p>'),
     ('盲点', '<p>stat 比较是启发式的:内容改了但大小不变、mtime 又被恢复,只要 ctime 也不比较(<code>core.trustctime=false</code> 加 <code>core.checkStat=minimal</code>),git 就看不出来。默认配置下原地写文件会更新 ctime,把这个改动暴露出来。</p>'),
     ('值多少钱', '<p>10,000 个小文件,缓存有效 29 ms;缓存全失效要重读所有文件,204 ms,大约 7 倍。文件越多、越大,差距越大。</p>'),
     ('搬仓库', '<p><code>cp -a</code> 保留 mtime 但 inode 与 ctime 变了,index 里的缓存整体失效,第一次 <code>git status</code> 慢(734 ms),第二次恢复。把 stat 检查放宽到 mtime 和 size 可以避开,但放弃了 ctime 带来的保护。</p>')],
    steps,
    [ENV_I_GIT + '。文件系统是 macOS APFS(纳秒级时间戳);index 解析器是我写的 Python(ll.py 的 parse_index,只处理 v2/v3);耗时 3 次中位数,含进程启动;第四节在每次计时前等过 1 秒以避开 racy 窗口(原因见下一篇)',
     '没有验证:index v4(路径前缀压缩)、split index、sparse index 的 stat 保存;Linux / Windows 上 stat 字段的差异(dev、ino 的稳定性);core.checkStat 的 default 与 minimal 之间每个字段的具体取舍;fsmonitor 与 untracked cache(见后面一篇)'],
    'index 的 stat 缓存')
